package systembackupsecurity

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestS3SigningMatchesIndependentAClientVector(t *testing.T) {
	// Generated by the existing A-owned Python sign() implementation using
	// synthetic credentials. Pins interop independently of the Go encoder.
	want := "AWS4-HMAC-SHA256 Credential=test-access/20260924/us-east-1/s3/aws4_request,SignedHeaders=host;x-amz-content-sha256;x-amz-date,Signature=9d110395365558c187dc21e202fbb8d202f9d5b1a0e2b968e75f75627a3fd6d3"
	got, date := s3Authorization("GET", "/bucket/part/a%20b%2Bc", "versionId=v%2B1", "minio.example:9000", "test-access", "test-secret", time.Date(2026, 9, 24, 8, 0, 0, 0, time.UTC))
	if got != want || date != "20260924T080000Z" {
		t.Fatal("SigV4 interop mismatch")
	}
}

func TestS3URIEscaping(t *testing.T) {
	for _, c := range []struct {
		in, want string
		slash    bool
	}{{"a b+c/%~", "a%20b%2Bc%2F%25~", false}, {"a b+c/%~", "a%20b%2Bc/%25~", true}, {"中文", "%E4%B8%AD%E6%96%87", false}} {
		if got := awsURI(c.in, c.slash); got != c.want {
			t.Fatalf("URI got=%s want=%s", got, c.want)
		}
	}
}
func TestS3ReadClientPinsVersionAndNeverTreatsErrorsAsAbsence(t *testing.T) {
	for _, mode := range []string{"valid", "forbidden", "not-found", "redirect", "wrong-version", "unversioned", "delete-marker"} {
		t.Run(mode, func(t *testing.T) {
			server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.EscapedPath() != "/test-bucket/part/a%20b%2Bc" || r.URL.RawQuery != "versionId=v%2B1" || !strings.Contains(r.Header.Get("Authorization"), "SignedHeaders=host;x-amz-content-sha256;x-amz-date") || r.Header.Get("X-Amz-Content-Sha256") != registrationHash("") {
					t.Error("request lost exact object binding")
					w.WriteHeader(400)
					return
				}
				switch mode {
				case "forbidden":
					http.Error(w, "PRIVATE", 403)
					return
				case "not-found":
					w.WriteHeader(404)
					return
				case "redirect":
					w.Header().Set("Location", "https://example.invalid")
					w.WriteHeader(307)
					return
				}
				version := "v+1"
				if mode == "wrong-version" {
					version = "v+2"
				}
				if mode == "unversioned" {
					version = "null"
				}
				if mode == "delete-marker" {
					w.Header().Set("X-Amz-Delete-Marker", "true")
				}
				w.Header().Set("X-Amz-Version-Id", version)
				w.Header().Set("Content-Length", "3")
				if r.Method == "GET" {
					io.WriteString(w, "abc")
				}
			}))
			defer server.Close()
			client := server.Client()
			client.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
			c := s3ReadClient{endpoint: server.URL, access: "read-only", secret: "test-only", http: client}
			info, err := c.StatObject(context.Background(), "test-bucket", "part/a b+c", s3VersionOptions{VersionID: "v+1"})
			if mode == "valid" {
				if err != nil || info.VersionID != "v+1" || info.Size != 3 {
					t.Fatal("valid versioned object rejected", err)
				}
				body, err := c.GetObject(context.Background(), "test-bucket", "part/a b+c", s3VersionOptions{VersionID: info.VersionID})
				if err != nil {
					t.Fatal(err)
				}
				defer body.Close()
				b, _ := io.ReadAll(body)
				if string(b) != "abc" {
					t.Fatal("GET body drift")
				}
			} else if err == nil || strings.Contains(err.Error(), "PRIVATE") {
				t.Fatal("provider uncertainty accepted or leaked")
			}
		})
	}
}
